k = 60
base = [3, 1, 4, 2, 5]
q1 = [1, 3, 2, 5, 4]
q2 = [4, 2, 1, 3, 5]

def rrf(lists):
    s = {}
    for l in lists:
        for rank, doc in enumerate(l, start=1):
            s[doc] = s.get(doc, 0.0) + 1.0 / (k + rank)
    return [d for d, _ in sorted(s.items(), key=lambda x: -x[1])]

fused = rrf([base, q1, q2])
relevant = {1, 3}

def recall(l, rel):
    return len(set(l[:3]) & rel) / len(rel)

print('单query排名 =', base)
print('多query RRF融合排名 =', fused)
print('单query Recall@3 =', round(recall(base, relevant), 4))
print('融合 Recall@3 =', round(recall(fused, relevant), 4))
